const modules = [
 {name:'Carbohydrate Metabolism',icon:'◈',source:'Ch14 · Ch20',core:['Glycolysis','Gluconeogenesis','Glycogen Metabolism','Pentose Phosphate Pathway'],extra:['Fructose Metabolism','Galactose Metabolism']},
 {name:'Citric Acid Cycle & Energy',icon:'◎',source:'Ch16 · Ch19-I',core:['Citric Acid Cycle','Oxidative Phosphorylation','Pyruvate Oxidation'],extra:['NADH Shuttles','Anaplerotic Reactions']},
 {name:'Lipid Metabolism',icon:'◇',source:'Ch17 · Ch21',core:['Fatty Acid β-Oxidation','Fatty Acid Biosynthesis','Ketone Body Metabolism','Cholesterol Metabolism'],extra:['Triacylglycerol Metabolism','Lipoprotein Transport','Glycerophospholipid Biosynthesis']},
 {name:'Amino Acid & Nitrogen Metabolism',icon:'⌁',source:'Ch18',core:['Urea Cycle','Amino Acid Catabolism'],extra:['Nitrogen Transport','Branched-Chain Amino Acid Catabolism']},
 {name:'Photosynthesis & Plant Metabolism',icon:'✳',source:'Ch16 · Ch19-II · Ch20',core:['Calvin–Benson Cycle','Light Reactions','Glyoxylate Cycle'],extra:['Photorespiration','C₄ Carbon Assimilation','Starch & Sucrose Metabolism']},
 {name:'Interorgan Cycles',icon:'⇄',source:'Ch14 · Ch18 · Ch20',core:['Cori Cycle','Glucose–Alanine Cycle'],extra:[]}
];
const cells={Animal:['Hepatocyte','Skeletal Muscle Cell','Cardiomyocyte','Adipocyte','Brown Adipocyte','Renal Cell / Renal Cortex','Brain Cell / Brain Tissue','Intestinal Epithelial Cell','Mammary Gland Cell','Adrenal Cortex Cell','Endothelial Cell'],Plant:['C₃ Photosynthetic Cell','C₄ Mesophyll Cell','C₄ Bundle Sheath Cell','Germinating Seed Cell','General Plant Cell'],Microbial:['Yeast Cell','Escherichia coli','Anaerobic Bacterium','Purple Photosynthetic Bacterium','Green Sulfur Bacterium','Cyanobacterium','Algal Cell','Red Algal Cell','General Bacterial Cell']};
const descriptions={Glycolysis:'Follow the conversion of glucose to pyruvate, and explore its place in cellular metabolism.',Gluconeogenesis:'Explore glucose production and its coordinated regulation with glycolysis.','Citric Acid Cycle':'Explore the central meeting point of carbohydrate, lipid, and amino acid metabolism.','Oxidative Phosphorylation':'Connect electron transport, the proton gradient, and ATP synthesis.','Urea Cycle':'Explore nitrogen disposal and the connections between the urea and citric acid cycles.','Calvin–Benson Cycle':'Explore carbon fixation, reduction, and regeneration in photosynthetic metabolism.','Light Reactions':'Explore linear and cyclic electron flow, and the production of ATP and NADPH.','Cori Cycle':'Follow metabolic cooperation between muscle and liver through lactate and glucose.','Glucose–Alanine Cycle':'Follow the exchange of carbon and nitrogen between muscle and liver.'};
const connections={Glycolysis:['Gluconeogenesis','Citric Acid Cycle','Pentose Phosphate Pathway'],Gluconeogenesis:['Glycolysis','Cori Cycle','Glucose–Alanine Cycle'],'Citric Acid Cycle':['Pyruvate Oxidation','Oxidative Phosphorylation','Urea Cycle'],'Urea Cycle':['Citric Acid Cycle','Amino Acid Catabolism','Nitrogen Transport'],'Fatty Acid β-Oxidation':['Fatty Acid Biosynthesis','Ketone Body Metabolism','Citric Acid Cycle'],'Fatty Acid Biosynthesis':['Fatty Acid β-Oxidation','Pentose Phosphate Pathway','Triacylglycerol Metabolism'],'Calvin–Benson Cycle':['Light Reactions','Photorespiration','Starch & Sucrose Metabolism'],'Light Reactions':['Calvin–Benson Cycle','Oxidative Phosphorylation'],'Cori Cycle':['Glycolysis','Gluconeogenesis'],'Glucose–Alanine Cycle':['Gluconeogenesis','Urea Cycle','Amino Acid Catabolism']};
const subviews={'Glycogen Metabolism':['Synthesis','Breakdown','Reciprocal regulation'],'Oxidative Phosphorylation':['Electron transport','Proton gradient','ATP synthase'],'Ketone Body Metabolism':['Ketogenesis','Ketolysis'],'Cholesterol Metabolism':['Biosynthesis','Regulation','Metabolic fates'],'Amino Acid Catabolism':['Carbon skeletons','Glucogenic amino acids','Ketogenic amino acids'],'Light Reactions':['Linear electron flow','Cyclic electron flow'],'NADH Shuttles':['Malate–aspartate','Glycerol 3-phosphate'],'Starch & Sucrose Metabolism':['Starch synthesis','Sucrose synthesis']};
const $=id=>document.getElementById(id);
const state={group:'Animal',cell:'Hepatocyte',path:'Glycolysis',tab:'Overview',open:new Set([0]),extra:new Set(),layers:{'Metabolite labels':true,'Enzyme names':true,'Cell compartments':false,'Energy & redox':false},details:true};
try{const saved=JSON.parse(localStorage.getItem('metabolic-atlas-ui')||'null');if(saved&&cells[saved.group]?.includes(saved.cell)&&modules.some(m=>[...m.core,...m.extra].includes(saved.path))){Object.assign(state,{group:saved.group,cell:saved.cell,path:saved.path});state.open.add(modules.findIndex(m=>[...m.core,...m.extra].includes(state.path)));}}catch{}
function save(){try{localStorage.setItem('metabolic-atlas-ui',JSON.stringify({group:state.group,cell:state.cell,path:state.path}));}catch{}}
function moduleFor(path=state.path){return modules.find(m=>[...m.core,...m.extra].includes(path));}
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('show'),2400);}
function renderCells(){ $('groups').replaceChildren(...Object.keys(cells).map(group=>{const b=document.createElement('button');b.textContent=group;b.className=group===state.group?'active':'';b.setAttribute('aria-pressed',group===state.group);b.onclick=()=>{state.group=group;state.cell=cells[group][0];save();renderCells();renderMain();};return b;}));$('cell').replaceChildren(...cells[state.group].map(name=>{const opt=new Option(name,name);opt.selected=name===state.cell;return opt;}));$('cell-label').textContent=state.group==='Microbial'?'Microbial context':state.group+' cell';}
function selectPath(path){state.path=path;const i=modules.findIndex(m=>[...m.core,...m.extra].includes(path));state.open.add(i);if(modules[i].extra.includes(path))state.extra.add(i);$('search').value='';document.body.classList.remove('menu-open');save();renderNav();renderMain();}
function renderNav(){const query=$('search').value.trim().toLowerCase();$('modules').replaceChildren();let matches=0;modules.forEach((m,i)=>{const paths=[...m.core,...m.extra].filter(p=>p.toLowerCase().includes(query));if(!paths.length)return;matches+=paths.length;const section=document.createElement('section');section.className='module';const expanded=state.open.has(i)||!!query;const heading=document.createElement('button');heading.className='module-heading';heading.setAttribute('aria-expanded',expanded);heading.innerHTML=`<span class="module-symbol">${m.icon}</span><span>${m.name}</span><span class="chevron">${expanded?'⌃':'⌄'}</span>`;heading.onclick=()=>{state.open.has(i)?state.open.delete(i):state.open.add(i);renderNav();};section.append(heading);if(expanded){const list=document.createElement('div');list.className='path-list';paths.filter(p=>query||m.core.includes(p)||state.extra.has(i)).forEach(path=>{const b=document.createElement('button');b.className='path'+(path===state.path?' active':'');b.textContent=path;if(path===state.path){b.setAttribute('aria-current','page');const a=document.createElement('span');a.className='arrow';a.textContent='↗';b.append(a);}b.onclick=()=>selectPath(path);list.append(b);});section.append(list);if(m.extra.length&&!query){const more=document.createElement('button');more.className='more';more.textContent=state.extra.has(i)?'− Hide extensions':`+ ${m.extra.length} more pathways`;more.setAttribute('aria-expanded',state.extra.has(i));more.onclick=()=>{state.extra.has(i)?state.extra.delete(i):state.extra.add(i);renderNav();};section.append(more);}}$('modules').append(section);});if(!matches){const p=document.createElement('p');p.className='no-results';p.textContent='No pathways found. Try a different name.';$('modules').append(p);}$('path-count').textContent=query?`${matches} found`:'18 core';$('collapse').textContent=state.open.size?'Collapse all':'Expand all';}
function renderMain(){const m=moduleFor();$('breadcrumb-module').textContent=m.name;$('breadcrumb-path').textContent=state.path;$('chapter').textContent=`${m.source.replaceAll('Ch','CHAPTER ')} / COURSE LIBRARY`;$('title').textContent=state.path;$('description').textContent=descriptions[state.path]||`Explore ${state.path.toLowerCase()} and its connections within the course.`;$('priority').textContent=m.core.includes(state.path)?'Core pathway':'Extension';$('canvas-cell').textContent=state.cell;$('detail-title').textContent=state.path;$('detail-cell').textContent=state.cell;$('detail-module').textContent=m.name;$('detail-source').textContent=m.source;$('tabs').replaceChildren(...['Overview','Connections','Regulation'].map((tab,i)=>{const b=document.createElement('button');b.className='tab'+(state.tab===tab?' active':'');b.innerHTML=`<span aria-hidden="true">${['▦','⇄','≋'][i]}</span>${tab}`;b.setAttribute('role','tab');b.setAttribute('aria-selected',state.tab===tab);b.onclick=()=>{state.tab=tab;renderMain();};return b;}));
 const views={Overview:['PATHWAY WORKSPACE','A space to explore the pathway','The reaction map will appear here. For now, explore cell types, pathways, and viewing options.'],Connections:['CONNECTED METABOLISM','See how pathways connect','Metabolite links, transport routes, and shared intermediates will appear here. Explore the related pathways below.'],Regulation:['METABOLIC CONTROL','Explore what controls the pathway','Activators, inhibitors, and coordinated regulation will appear here, with cell-specific context.']};const [k,t,d]=views[state.tab];$('empty-kicker').textContent=k;$('empty-title').textContent=t;$('empty-description').textContent=d;
 const chips=state.tab==='Overview'?(subviews[state.path]||Object.entries(state.layers).filter(([,on])=>on).map(([name])=>name)):state.tab==='Connections'?['Metabolite flow','Transport','Shared intermediates']:['Activation','Inhibition','Coordinated control'];$('empty-chips').replaceChildren(...chips.map(name=>{const s=document.createElement('span');s.textContent=name;return s;}));
 $('layers').replaceChildren(...Object.entries(state.layers).map(([name,on])=>{const label=document.createElement('label');label.className='switch-row';label.append(document.createTextNode(name));const input=document.createElement('input');input.type='checkbox';input.checked=on;input.setAttribute('role','switch');input.setAttribute('aria-label',name);input.onchange=()=>{state.layers[name]=input.checked;renderMain();};label.append(input);return label;}));
 const related=connections[state.path]||[...m.core,...m.extra].filter(p=>p!==state.path).slice(0,3);$('related-heading').textContent=connections[state.path]?'Related pathways':'In this module';$('related-links').replaceChildren(...related.map(path=>{const b=document.createElement('button');b.className='related-link';b.append(document.createTextNode(path));const a=document.createElement('span');a.textContent='↗';b.append(a);b.onclick=()=>selectPath(path);return b;}));$('details').hidden=!state.details;document.querySelector('.content').classList.toggle('no-details',!state.details);$('details-toggle').setAttribute('aria-expanded',state.details);}
$('cell').onchange=e=>{state.cell=e.target.value;save();renderMain();};$('search').oninput=renderNav;$('collapse').onclick=()=>{state.open=state.open.size?new Set():new Set(modules.map((_,i)=>i));renderNav();};$('details-toggle').onclick=()=>{state.details=!state.details;renderMain();};$('reset').onclick=()=>{state.tab='Overview';state.layers={'Metabolite labels':true,'Enzyme names':true,'Cell compartments':false,'Energy & redox':false};state.details=true;renderMain();notify('View options reset');};$('presentation').onclick=()=>{const on=document.body.classList.toggle('presentation');$('presentation').setAttribute('aria-pressed',on);$('presentation').querySelector('span').textContent=on?'Exit presentation':'Presentation mode';};$('mobile-menu').onclick=()=>document.body.classList.toggle('menu-open');document.querySelector('.brand').onclick=e=>{e.preventDefault();selectPath('Glycolysis');};document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar')&&!e.target.closest('#mobile-menu'))document.body.classList.remove('menu-open');});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open','presentation');$('presentation').setAttribute('aria-pressed','false');$('presentation').querySelector('span').textContent='Presentation mode';}if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();document.body.classList.remove('presentation');if(innerWidth<=650)document.body.classList.add('menu-open');$('search').focus();}});renderCells();renderNav();renderMain();
